export default async function ({ event, tags }, ctx) {
  if (!event.id || !event.title || !event.content || !tags.length)
    throw Error("Missing article or tags");
  const key = "wp-demo-post:" + event.id,
    prev = await ctx.state.get(key);
  if (prev?.phase === "pending") throw Error("Inspect WordPress before clearing pending post");
  if (prev?.phase === "done") return { skip: true, postId: prev.id, title: "", content: "", tags };
  await ctx.state.set(key, { phase: "pending" });
  return {
    skip: false,
    postId: 0,
    title: "Demo tagging post: " + event.title,
    content:
      "This is a post to demo automatic tagging a WordPress post via n8n. The following content could be rewritten in full or part with commentary using AI.\n\n" +
      event.content,
    tags,
  };
}

