export default async function ({ event, post }, ctx) {
  if (!Number.isSafeInteger(post?.id) || post.id < 1) throw Error("Unknown post creation");
  await ctx.state.set("wp-demo-post:" + event.id, { phase: "done", id: post.id });
  return { id: post.id };
}

