export default function ({ tags, previous, id }) {
  if (!Array.isArray(tags) || !tags.length || tags.some((t) => typeof t !== "string" || !t.trim()))
    throw Error("Provide at least one tag name");
  const unique = new Map();
  for (const name of tags) {
    const slug = name.trim().toLowerCase().replace(/\s+/g, "-");
    if (!unique.has(slug)) unique.set(slug, name.trim());
  }
  const entries = [...unique],
    index = previous?.index ?? 0,
    ids = previous?.ids ?? [];
  if (index > 0) {
    if (!Number.isSafeInteger(id) || id < 1) throw Error("Missing resolved tag ID");
    ids.push(id);
  }
  if (index >= entries.length)
    return { state: { index, ids }, more: false, slug: "unused", name: "unused", tag_ids: ids };
  const [slug, name] = entries[index];
  return { state: { index: index + 1, ids }, more: true, slug, name, tag_ids: ids };
}

