export default function ({ tags, slug }) {
  const a = tags.filter((x) => x.slug === slug);
  if (a.length > 1) throw Error("Ambiguous tag");
  const id = a[0]?.id ?? 0;
  if (id && (!Number.isSafeInteger(id) || id < 1)) throw Error("Invalid tag ID");
  return { found: !!id, id };
}

