export default async function ({ tag, slug }, ctx) {
  if (!Number.isSafeInteger(tag?.id) || tag.id < 1 || tag.slug !== slug)
    throw Error("Unknown tag creation");
  await ctx.state.set("wp-tag:" + slug, { phase: "done", id: tag.id });
  return { id: tag.id };
}

